function add(entry){var key=entry.url||entry.svg||entry.html;if(seen.has(key)){var e=seen.get(key);if(e.contexts.indexOf(entry.context)<0)e.contexts.push(entry.context);return;}entry.contexts=[entry.context];entry.source=photoDetails[entry.url]?photoDetails[entry.url].sourceHTML.replace(/<[^>]*>/g,''):sources[entry.url]||entry.source||'';entry.number=entries.length+1;seen.set(key,entry);entries.push(entry);}
function validImage(url){return /^assets\/(ilustracoes|fig)\//.test(url)||/^https:\/\/watlfdjcgfxmzymztmvc\.supabase\.co\/storage\/v1\/object\/public\/imagens\//.test(url);}
function media(html,context,href){if(!html)return;var t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('img').forEach(function(im){var url=im.getAttribute('src')||'';if(validImage(url))add({url:url,title:context,context:context,href:href,type:'Imagem'});});t.content.querySelectorAll('svg:not(.i)').forEach(function(svg){var safe=svg.cloneNode(true);safe.querySelectorAll('script,foreignObject,image,use,a').forEach(function(n){n.remove();});[safe].concat(Array.from(safe.querySelectorAll('*'))).forEach(function(n){Array.from(n.attributes).forEach(function(a){if(/^on/i.test(a.name)||/href$/i.test(a.name))n.removeAttribute(a.name);});});add({svg:safe.outerHTML,title:context,context:context,href:href,type:'Esquema'});});if(!t.content.querySelector('img,svg:not(.i)'))t.content.querySelectorAll('figure.manual-figure').forEach(function(figure){var safe=figure.cloneNode(true);safe.querySelectorAll('script,style,iframe,object,embed,form,input,button,link,meta').forEach(function(n){n.remove();});[safe].concat(Array.from(safe.querySelectorAll('*'))).forEach(function(n){Array.from(n.attributes).forEach(function(a){if(a.name!=='class')n.removeAttribute(a.name);});});add({html:safe.outerHTML,title:context,context:context,href:href,type:'Esquema',source:'Esquema baseado na definição de caso do manual INS/MISAU.'});});}
Object.keys(window.DISEASES||{}).forEach(function(slug){var d=window.DISEASES[slug],href='doenca.html?slug='+encodeURIComponent(slug);(d.cases||[]).forEach(function(c){media(c.media,d.name+' — Caso '+c.label.toLowerCase(),href);});(d.risks||[]).forEach(function(r,i){media(r.media,d.name+' — Grupo de risco '+(i+1),href);});['illus','evo','evolution'].forEach(function(k){media(d[k],d.name,href);});(d.secfull||[]).forEach(function(sec){if(sec.img&&validImage(sec.img))add({url:sec.img,title:d.name+' — '+sec.t,context:d.name,href:href,type:'Imagem'});(sec.items||[]).forEach(function(it){if(typeof it[1]==='string'&&/<(?:img|svg)\b/.test(it[1]))media(it[1],d.name+' — '+sec.t,href);});});});
(window.MANUAL&&MANUAL.sections||[]).forEach(function(sc){(sc.figures||[]).forEach(function(f){if(validImage(f.file))add({url:f.file,title:(f.caption||'Figura '+f.num).split(/\s+Fonte\s*:\s*/i)[0],context:'Secção '+sc.id,href:'seccao.html?id='+sc.id,type:'Figura'});});});
var grid=document.getElementById('image-grid');entries.forEach(function(e){var card=document.createElement('figure');card.className='image-card';card.dataset.search=(e.title+' '+e.contexts.join(' ')+' '+e.type+' '+e.source).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(e.url){var img=document.createElement('img');img.src=e.url;img.alt=e.title;img.loading='lazy';img.decoding='async';card.appendChild(img);}else if(e.html){var box=document.createElement('div');box.className='diagram diagram-html';box.innerHTML=e.html;card.appendChild(box);}else{var box=document.createElement('div');box.className='diagram';box.innerHTML=e.svg;card.appendChild(box);}var cap=document.createElement('figcaption'),title=document.createElement('strong');title.textContent=e.type==='Figura'?e.title:'Imagem '+e.number+'. '+e.title;cap.appendChild(title);var ctx=document.createElement('p');ctx.textContent=(photoDetails[e.url]&&photoDetails[e.url].description)||e.contexts.join(' · ');cap.appendChild(ctx);if(e.source||photoDetails[e.url]){var source=document.createElement('p');source.className='source';if(photoDetails[e.url]){source.innerHTML='<b>Fonte:</b> '+photoDetails[e.url].sourceHTML;}else{source.textContent='Fonte: '+e.source;}cap.appendChild(source);}var a=document.createElement('a');a.href=e.href;a.textContent='Consultar conteúdo';cap.appendChild(a);card.appendChild(cap);grid.appendChild(card);});
var input=document.getElementById('image-filter');input.value=new URLSearchParams(location.search).get('q')||'';
function filter(){var words=input.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().split(/\s+/).filter(Boolean),count=0;Array.from(grid.children).forEach(function(card){card.hidden=!words.every(function(w){return card.dataset.search.indexOf(w)>=0;});if(!card.hidden)count++;});document.getElementById('image-count').textContent=count+' de '+entries.length+' imagens e esquemas';document.getElementById('image-empty').hidden=count!==0;}
input.addEventListener('input',filter);filter();
window.IMAGE_GALLERY_ENTRIES=entries;
